scene.background=new THREE.Color('#dfa85f'); scene.fog=new THREE.Fog('#dfa85f',26,78);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.1,120); camera.position.set(0,1.65,7);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; host.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#ffe3b2','#754528',2.1)); const sun=new THREE.DirectionalLight('#fff0c9',3.1);sun.position.set(-8,13,5);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const mat=(color,roughness=.84)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={sand:mat('#bd8146'),darkSand:mat('#8c5833'),wood:mat('#643c28'),lightWood:mat('#ad7140'),red:mat('#a64532'),cream:mat('#e6c997'),dark:mat('#35231c'),metal:new THREE.MeshStandardMaterial({color:'#c6a567',metalness:.68,roughness:.3}),green:mat('#43543a'),horse:mat('#855036'),mane:mat('#38251e'),white:mat('#f2deba')};
function mesh(geo,material,parent=scene){const m=new THREE.Mesh(geo,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(parent,x,y,z,sx,sy,sz,material){let m=mesh(new THREE.BoxGeometry(sx,sy,sz),material,parent);m.position.set(x,y,z);return m}
function cylinder(parent,x,y,z,rt,rb,h,material,seg=10){let m=mesh(new THREE.CylinderGeometry(rt,rb,h,seg),material,parent);m.position.set(x,y,z);return m}
// Vast dusty main street
const ground=mesh(new THREE.PlaneGeometry(150,150),mats.sand);ground.rotation.x=-Math.PI/2;ground.position.y=-.05;
const grid=new THREE.GridHelper(120,50,'#d39b62','#c58a53');grid.position.y=-.035;grid.material.transparent=true;grid.material.opacity=.13;scene.add(grid);
// distant sculpted mesas
for(let i=0;i<11;i++){let x=-40+i*8,z=-28-(i%3)*5,h=7+(i*7%11),w=5+(i*3%5);let mesa=mesh(new THREE.ConeGeometry(w,h,5),i%2?mat('#a7613d'):mat('#bd7645'));mesa.position.set(x,h*.48,z);mesa.rotation.y=i*1.7;mesa.castShadow=false;}
// Saloon facade and porch
const saloon=new THREE.Group();scene.add(saloon);saloon.position.set(0,0,-24);
box(saloon,0,3.3,0,13,6.6,1.4,mats.wood);box(saloon,0,6.8,0,14,.45,1.7,mats.dark);
// roof as two slanted slabs
let roof=box(saloon,0,7.15,-.35,14,.3,2.4,mats.red);roof.rotation.x=-.1;
box(saloon,0,5.25,.78,3.7,1.8,.12,mats.dark);box(saloon,0,5.27,.87,3.4,1.5,.1,mats.lightWood);
for(let s of [-1,1]){box(saloon,s*4.3,3.7,.8,2.1,2.5,.14,mats.dark);box(saloon,s*4.3,3.8,.9,1.8,2.1,.08,mats.red);box(saloon,s*4.3,3.8,.96,1.3,1.6,.04,mats.cream);box(saloon,s*4.3,2.45,.65,2.8,.24,2.8,mats.wood);for(let x of [-1,1])box(saloon,s*4.3+x,1.5,1.8,.18,2.2,.18,mats.lightWood);}
// hanging sign
box(saloon,0,8.2,1.15,5.4,.95,.18,mats.dark);box(saloon,0,8.2,1.27,5.05,.68,.08,mats.red);
// Western props and cacti
function cactus(x,z,s=1){let g=new THREE.Group();scene.add(g);g.position.set(x,0,z);cylinder(g,0,1.1,0,.24*s,.32*s,2.2*s,mats.green,8);for(let side of [-1,1]){cylinder(g,side*.38*s,1.05*s,0,.18*s,.21*s,.95*s,mats.green,8);let arm=box(g,side*.26*s,1.38*s,0,.22*s,.65*s,.3*s,mats.green);arm.rotation.z=side*-.23;} }
for(let i=0;i<13;i++){let x=(i%2?1:-1)*(8+(i*13%9)),z=-8-(i*11%20);cactus(x,z,.8+(i%3)*.17);}
for(let s of [-1,1]){for(let i=0;i<4;i++){let z=-4-i*5;box(scene,s*11,.5,z,1.2,1,1.2,mats.wood);}}
// Hand-built hobby horse weapon in the lower right, parented to camera
const weapon=new THREE.Group();camera.add(weapon);weapon.position.set(.66,-.55,-1.05);weapon.rotation.set(-.05,-.13,-.11);
// little saddle grip
let handle=cylinder(weapon,0,-.22,.1,.15,.13,.62,mats.lightWood,12);handle.rotation.x=-.25;
// horse head points forward (-Z)
let skull=mesh(new THREE.SphereGeometry(.29,16,12),mats.horse,weapon);skull.scale.set(.85,1.05,1.25);skull.position.set(0,.1,-.35);
let muzzle=mesh(new THREE.SphereGeometry(.2,14,10),mats.lightWood,weapon);muzzle.scale.set(.95,.75,1.05);muzzle.position.set(0,-.05,-.62);
let blaze=mesh(new THREE.SphereGeometry(.055,10,8),mats.cream,weapon);blaze.scale.set(.8,2.5,.5);blaze.position.set(0,.16,-.58);
for(let s of [-1,1]){let ear=mesh(new THREE.ConeGeometry(.09,.32,8),mats.horse,weapon);ear.position.set(s*.16,.39,-.23);ear.rotation.z=-s*.18;let eye=mesh(new THREE.SphereGeometry(.047,10,8),mats.dark,weapon);eye.position.set(s*.22,.16,-.49);let nostril=mesh(new THREE.SphereGeometry(.027,8,6),mats.dark,weapon);nostril.position.set(s*.13,-.08,-.78);}
let mane=mesh(new THREE.SphereGeometry(.22,12,10),mats.mane,weapon);mane.scale.set(1.15,1.55,1.3);mane.position.set(0,.3,-.13);
for(let i=0;i<5;i++){let tuft=mesh(new THREE.ConeGeometry(.09,.27,7),mats.mane,weapon);tuft.position.set((i-2)*.08,.46,-.17-i*.09);tuft.rotation.x=-.5;}
let horseshoe=mesh(new THREE.TorusGeometry(.17,.045,7,16,Math.PI*1.55),mats.metal,weapon);horseshoe.position.set(0,-.16,-.84);horseshoe.rotation.z=Math.PI;

