for(let i=0;i<5;i++){let tuft=mesh(new THREE.ConeGeometry(.09,.27,7),mats.mane,weapon);tuft.position.set((i-2)*.08,.46,-.17-i*.09);tuft.rotation.x=-.5;}
let horseshoe=mesh(new THREE.TorusGeometry(.17,.045,7,16,Math.PI*1.55),mats.metal,weapon);horseshoe.position.set(0,-.16,-.84);horseshoe.rotation.z=Math.PI;
// Bandit targets: goofy wooden cowboy dummies with bright bullseye vests
const targets=[], projectiles=[];let score=0,health=100,wave=1,playing=false,paused=false,shotWait=0,toastWait=0,damageFlash=0;
function makeTarget(index,count){
 const g=new THREE.Group();scene.add(g);let side=(Math.random()-.5)*18;g.position.set(side,0,-13-Math.random()*12);g.userData={alive:true,phase:Math.random()*6, speed:.65+Math.random()*.38, hitFlash:0};
 let tunic=index%3===0?mat('#50715b'):index%3===1?mats.red:mat('#705444');
 let torso=mesh(new THREE.CylinderGeometry(.36,.52,1.15,10),tunic,g);torso.position.y=1.35;
 let belt=mesh(new THREE.CylinderGeometry(.39,.42,.13,10),mats.dark,g);belt.position.y=1.12;
 let head=mesh(new THREE.SphereGeometry(.35,12,10),mat('#d69d70'),g);head.position.y=2.15;
 let hat=mesh(new THREE.CylinderGeometry(.42,.42,.13,12),mats.dark,g);hat.position.y=2.48;let crown=mesh(new THREE.CylinderGeometry(.25,.3,.3,10),mats.dark,g);crown.position.y=2.68;
 for(let s of [-1,1]){let leg=mesh(new THREE.CylinderGeometry(.13,.16,.75,8),mats.dark,g);leg.position.set(s*.23,.45,0);let arm=mesh(new THREE.CylinderGeometry(.12,.15,.78,8),tunic,g);arm.position.set(s*.48,1.57,0);arm.rotation.z=s*.48;let hand=mesh(new THREE.SphereGeometry(.12,8,7),mat('#d69d70'),g);hand.position.set(s*.68,1.27,0);}
 let badge=mesh(new THREE.CircleGeometry(.17,10),mats.metal,g);badge.position.set(-.19,1.45,.37);
 g.userData.hittables=[torso,head,hat,crown,...g.children];g.userData.index=index;targets.push(g);return g;
}
function spawnWave(){let count=Math.min(3+wave,8);for(let i=0;i<count;i++)makeTarget(i,count);document.querySelector('#wave').textContent=String(wave).padStart(2,'0');showToast(wave===1?'LÁ VÊM ELES!':`RODADA ${wave} — SEGURA A ÉGUA!`);}
function showToast(txt){const el=document.querySelector('#toast');el.textContent=txt;el.classList.add('show');toastWait=1.5;}
function updateHud(){document.querySelector('#score').textContent=String(score).padStart(4,'0');document.querySelector('#health').style.width=health+'%';document.querySelector('#healthNum').textContent=Math.ceil(health)+'%';}
function createShot(){if(!playing||paused||shotWait>0)return;shotWait=.33;weapon.position.y=-.48;weapon.rotation.x=-.22;let dir=new THREE.Vector3();camera.getWorldDirection(dir);let start=camera.position.clone().add(dir.clone().multiplyScalar(.7));
 let proj=mesh(new THREE.TorusGeometry(.14,.035,6,14,Math.PI*1.6),mats.metal);proj.position.copy(start);proj.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),dir);proj.userData={dir:dir.clone(),life:.75};projectiles.push(proj);
 const ray=new THREE.Raycaster(camera.position,dir,0,50);let best=null,bestDist=Infinity;
 for(const t of targets){if(!t.userData.alive)continue;const hits=ray.intersectObjects(t.children,true);if(hits.length&&hits[0].distance<bestDist){best=t;bestDist=hits[0].distance;}}
 if(best){best.userData.alive=false;best.userData.hitFlash=.4;score+=100+Math.max(0,Math.floor((24-bestDist)*4));showToast(['NO ALVO!','FERRADURA NA TESTA!','BELA PONTARIA!'][Math.floor(Math.random()*3)]);document.querySelector('#crosshair').classList.add('hit');setTimeout(()=>document.querySelector('#crosshair').classList.remove('hit'),120);}
 updateHud();
}

